294			\bigl\| \phi_{\mathrm{A}} \ot \phi_{\mathrm{B}} \ket{\psi} - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \bigr\|^2 \leq \delta_{\mathrm{qld}}\;.
295		\]
296		% Transfer step added: the source (lines 1864--1875 of
297		% 14_analysis_of_the_pauli_basis_test.tex) passes directly from the
298		% conjugation estimates of lem:qld-unitary, which concern the
299		% unitarily conjugated operators V (M_h ot Id) V^dagger, to the
300		% corresponding estimates for the isometry phi, whose conjugation
301		% inserts the projection onto its range; the range-projection
302		% argument below supplies the missing step.
303		Item~2 of Lemma~\ref{lem:qld-unitary} concerns the unitarily conjugated operators $N^W_h = V_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, V_{\mathrm{A}}^\dagger$, whereas conjugation by the isometry $\phi_{\mathrm{A}}$ additionally inserts the projection $Q_{\mathrm{A}} = \phi_{\mathrm{A}} \phi_{\mathrm{A}}^\dagger = V_{\mathrm{A}} \, \bigl(\ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}^{\ot M}\bigr)_{\mathrm{A}'\mathrm{A}''} \, V_{\mathrm{A}}^\dagger$ onto the range of $\phi_{\mathrm{A}}$: since $(M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}}$ and $\bigl(\ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}^{\ot M}\bigr)_{\mathrm{A}'\mathrm{A}''}$ act on disjoint registers and hence commute,
304		\[
305			\phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger
306			= V_{\mathrm{A}} \, \Bigl( (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \ot \bigl(\ket{\mathrm{EPR}_q}\bra{\mathrm{EPR}_q}^{\ot M}\bigr)_{\mathrm{A}'\mathrm{A}''} \Bigr) \, V_{\mathrm{A}}^\dagger
307			= N^W_h \, Q_{\mathrm{A}} = Q_{\mathrm{A}} \, N^W_h\;.
308		\]
309		The estimates transfer from $N^W_h$ to $\phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger$ as follows. Write $\ket{\Delta} = \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M}$ and $\ket{\vartheta} = \phi_{\mathrm{A}} \ot \phi_{\mathrm{B}} \ket{\psi}$. Since $\phi_{\mathrm{A}}^\dagger \phi_{\mathrm{A}} = \Id$, the projection $\Id - Q_{\mathrm{A}}$ annihilates $\ket{\vartheta}$, so the displayed bound above gives
310		\[
311			\bigl\| (\Id - Q_{\mathrm{A}}) \ket{\Delta} \bigr\|^2
312			= \bigl\| (\Id - Q_{\mathrm{A}}) (\ket{\Delta} - \ket{\vartheta}) \bigr\|^2
313			\leq \bigl\| \ket{\Delta} - \ket{\vartheta} \bigr\|^2
314			\leq \delta_{\mathrm{qld}}\;.
315		\]
316		Since the strategy is projective, the operators $N^W_h$, for $h \in \F_q^M$, are mutually orthogonal projectors summing to the identity, so $\sum_h \| N^W_h \ket{\xi} \|^2 = \| \ket{\xi} \|^2$ for every vector $\ket{\xi}$. Decomposing
317		\[
318			\bigl( \phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger - (\tau^W_h)_{\mathrm{A}''} \bigr) \ket{\Delta}
319			= \bigl( N^W_h - (\tau^W_h)_{\mathrm{A}''} \bigr) \ket{\Delta} - N^W_h (\Id - Q_{\mathrm{A}}) \ket{\Delta}
320		\]
321		and summing the squared norms over $h$ via $\| \xi - \xi' \|^2 \leq 2\|\xi\|^2 + 2\|\xi'\|^2$, the first terms contribute $O(\delta_{\mathrm{qld}})$ by Item~2 of Lemma~\ref{lem:qld-unitary} and the second terms contribute at most $2 \| (\Id - Q_{\mathrm{A}}) \ket{\Delta} \|^2 \leq 2\delta_{\mathrm{qld}}$; hence, for $W \in \{X,Z\}$,
322		\[
323			\phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger \approx_{\delta_{\mathrm{qld}}} (\tau^W_h)_{\mathrm{A}''}
324			\qquad \text{and, by the identical argument,} \qquad
325			\phi_{\mathrm{B}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{B}} \, \phi_{\mathrm{B}}^\dagger \approx_{\delta_{\mathrm{qld}}} (\tau^W_h)_{\mathrm{B}''}\;,
326		\]
327		where the $\approx$ statements hold with respect to the state $\ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M}$ and the answer summation is over $h \in \F_q^M$; the constant implicit in $\approx_{\delta_{\mathrm{qld}}}$ (Definition~\ref{def:povm-distance}) absorbs the factors accumulated above. This shows that the game $\mathfrak{G}^{\mathrm{Pauli}}_{(q,m,d)}$ is a self-test, with robustness $\delta_{\mathrm{qld}}(\eps,m,d,q)$, for the canonical Pauli strategy of Lemma~\ref{lem:pauli-completeness}. Identifying the registers $\mathrm{A}\mathrm{A}'$ with $\mathrm{A}'$ and $\mathrm{B}\mathrm{B}'$ with $\mathrm{B}'$ matches the statement of Theorem~\ref{thm:pauli}, in which $\phi_{\mathrm{A}}\colon \mathcal{H}_{\mathrm{A}} \to \mathcal{H}_{\mathrm{A}'} \ot \mathcal{H}_{\mathrm{A}''}$. Finally, unpacking the dependence on the parameters $\eps, m, d, q$, the function $\delta_{\mathrm{qld}}(\eps,m,d,q) = O(\delta_S^{1/4} + md/q)$ has the form $a(md)^a(\eps^b + q^{-b} + 2^{-bmd})$ for universal constants $a > 1$ and $0 < b < 1$; see Remark~\ref{rem:pauli-robustness-form} for the reconciliation of this form with the statement of Theorem~\ref{thm:pauli}.
328	\end{proof}
329	
330	\begin{remark}[Norm conventions in the robustness bound]\label{rem:pauli-robustness-form}
331		The proof above, following the source, establishes the first conclusion of Theorem~\ref{thm:pauli} in the squared form $\| \phi_{\mathrm{A}} \ot \phi_{\mathrm{B}} \ket{\psi} - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \|^2 \leq \delta_{\mathrm{qld}}$, whereas the theorem bounds the unsquared norm by $\delta_{\mathrm{qld}}(\eps,m,d,q)$. The two are reconciled by replacing the exponent $b$ with $b/2$ and enlarging $a$, since the class of functions $a(md)^a(\eps^b + q^{-b} + 2^{-bmd})$ is closed under square roots up to such adjustments of the universal constants. Similarly, the closing sentence of the source proof asserts constants $a > 1$ and $0 < b < 1$, while Theorem~\ref{thm:pauli} requires only $a \geq 1$ and $0 < b < 1$; the former implies the latter.
332	\end{remark}

